    "body": "<!--/head-->\n<!--header-->\n<!--/header-->\n<main class=\"support-form-page partnership-page\">\n    <section>\n        <div class=\"pj-container\">\n            <div class=\"page-py-5\">\n                <div class=\"page-title-2 pj-u-text-center\">\n                    <h3>제휴 문의</h3>\n                </div>\n                <!-- form -->\n                <form id=\"promoForm_jeju\" class=\"apply-form\" method=\"post\" novalidate data-apply-uploader>\n                    <div class=\"apply-wrap\">\n                        <!-- 이름 -->\n                        <div class=\"apply-item\">\n                            <label class=\"pj-label pj-u-fw-bold\" for=\"userName_jeju\">이름 <span class=\"pj-u-text-primary\">*</span></label>\n                            <input type=\"text\" id=\"userName_jeju\" class=\"pj-field\" placeholder=\"이름을 입력해 주세요.\" required>\n                        </div>\n                        <!-- 연락처 -->\n                        <div class=\"apply-item\">\n                            <label class=\"pj-label pj-u-fw-bold\" for=\"userPhone_jeju\">연락처 <span class=\"pj-u-text-primary\">*</span></label>\n                            <input type=\"tel\" id=\"userPhone_jeju\" class=\"pj-field\" placeholder=\"연락처를 입력해 주세요.\" required>\n                        </div>\n                        <!-- 이메일 -->\n                        <div class=\"apply-item\">\n                            <label class=\"pj-label pj-u-fw-bold\" for=\"userEmail_jeju\">이메일 <span class=\"pj-u-text-primary\">*</span></label>\n                            <input type=\"email\" id=\"userEmail_jeju\" class=\"pj-field\" placeholder=\"업무용 이메일을 입력해 주세요.\" required>\n                        </div>\n                        <!-- 기업/단체명 -->\n                        <div class=\"apply-item\">\n                            <label class=\"pj-label pj-u-fw-bold\" for=\"companyName_jeju\">기업/단체명 <span class=\"pj-u-text-primary\">*</span></label>\n                            <input type=\"text\" id=\"companyName_jeju\" class=\"pj-field\" placeholder=\"기업/단체명을 입력해 주세요.\" required>\n                        </div>\n                        <!-- 내용 + 첨부 -->\n                        <div class=\"apply-item apply-item--content\">\n                            <label class=\"pj-label pj-u-fw-bold\" for=\"message_jeju\">내용 <span class=\"pj-u-text-primary\">*</span></label>\n                            <div class=\"support-message-field\">\n                                <textarea name=\"content\" id=\"message_jeju\" class=\"pj-field support-message-field__textarea\"\n                                    rows=\"4\" placeholder=\"내용을 작성해 주세요.\" required></textarea>\n                                <div class=\"cmt-grid support-message-field__grid\"></div>\n                                <div class=\"support-message-field__tools\">\n                                    <label class=\"pj-button pj-button--link support-message-field__upload\" aria-label=\"이미지 첨부\">\n                                        <img src=\"../assets/images/svg/icon_photo.svg\" alt=\"\">\n                                        <input type=\"file\" class=\"pj-visually-hidden cmt-input\" accept=\"image/*\" multiple>\n                                    </label>\n                                </div>\n                            </div>\n                            <!-- 개인정보 수집 동의 -->\n                            <div class=\"apply-agree\">\n                                <div class=\"pj-check\">\n                                    <input class=\"pj-check-input\" type=\"checkbox\" id=\"agree_jeju\" required>\n                                    <label class=\"pj-check-label\" for=\"agree_jeju\">\n                                        개인정보 수집 및 이용에 동의 <span class=\"pj-u-text-primary\">(필수)</span>\n                                    </label>\n                                </div>\n                                <button type=\"button\" class=\"pj-button pj-button--link pj-button--text pj-button--text-under\" data-pj-toggle=\"modal\"\n                                    data-pj-target=\"#privacyModal_jeju\">\n                                    보기\n                                </button>\n                            </div>\n                        </div>\n                        <!-- 버튼 -->\n                        <div class=\"apply-cta\">\n                            <button type=\"button\" class=\"pj-button pj-button--md pj-button--gray\" data-pj-action=\"back\">취소</button>\n                            <button type=\"submit\" class=\"pj-button pj-button--md pj-button--primary\">작성하기</button>\n                        </div>\n                    </div>\n                </form>\n            </div>\n        </div>\n    </section>\n</main>\n<!-- 개인정보 Modal -->\n<div class=\"pj-modal pj-fade\" id=\"privacyModal_jeju\" tabindex=\"-1\" aria-labelledby=\"privacyModalLabel_jeju\" aria-hidden=\"true\">\n    <div class=\"pj-modal-dialog pj-modal-dialog--centered pj-modal-dialog--scrollable\">\n        <div class=\"pj-modal-content\">\n            <div class=\"pj-modal-header\">\n                <h1 class=\"pj-modal-title pj-u-fs-5\" id=\"privacyModalLabel_jeju\">개인정보 수집 및 이용동의</h1>\n                <button type=\"button\" class=\"pj-button-close\" data-pj-dismiss=\"modal\" aria-label=\"Close\"></button>\n            </div>\n            <div class=\"pj-modal-body\">\n                <strong>1. 수집 목적</strong><br>\n                문의 접수 및 처리, 회신을 위한 연락 목적<br><br>\n                <strong>2. 수집 항목</strong><br>\n                이름, 연락처, 이메일, 기업/단체명, 문의 내용<br><br>\n                <strong>3. 보유 및 이용기간</strong><br>\n                문의 처리 완료 후 6개월까지 보관 후 파기\n            </div>\n        </div>\n    </div>\n</div>\n<!--Nav-->\n<!--div id=\"sticky-menu\">\n    <div>\n        <button type=\"button\" class=\"pj-button pj-button--primary\" data-pj-toggle=\"modal\" data-pj-target=\"#kakaoModal\">\n            <img src=\"../assets/images/icon/talk-9.png\">\n        </button>\n    </div>\n    <div>\n        <button class=\"pj-button pj-button--kakao\" type=\"button\" data-pj-href=\"javascript:Kakao.Channel.chat({channelPublicId: '_tJxizxj'});\" data-pj-link-target=\"_blank\">\n            <i class=\"ri-kakao-talk-fill\"></i>\n        </button>\n    </div>\n</div-->\n<!--/Nav-->\n<script src=\"../assets/js/contact.js\"></script>\n<!--footer-->\n<!-- footer.html -->\n<!--Nav-->\n<!--/Nav-->\n<!-- Search -->\n<!--/Search-->\n<!-- Login -->\n<!-- /Login -->\n<!-- 이용약관 Modal -->\n<!-- 개인정보처리방침 Modal -->\n<!-- Footer Scripts -->\n<script src=\"../assets/vendor/flatpickr/flatpickr.min.js\"></script>\n<script src=\"../assets/vendor/flatpickr/ko.js\"></script>\n<script>\n    if (window.AOS) {\n        AOS.init({\n            offset: 48,\n            delay: 0,\n            duration: 600,\n            easing: 'ease-out-cubic',\n            once: true,\n            mirror: false,\n            throttleDelay: 80,\n            debounceDelay: 120\n        });\n    }\n</script>\n<script src=\"../assets/js/search-ui.js\"></script>\n<!-- Toast 컨테이너 -->\n<!-- Daum 주소 API -->\n<!-- /Footer Scripts -->"
